-- Complete the 52-competency editorial contract while keeping the established portal copy as baseline.
-- The richer DOCX was used only to QA and complete missing behaviour, miscalibration and barrier content.

with editorial(slug, title_no, title_en, category, summary, payload) as (
  values
    ('kommunikasjon', 'Kommunikasjon', 'Communication', 'foundation', 'Gjør budskap, retning og forventninger forståelige for bestemte mottakere, og bruker lytting til å sikre felles forståelse.', $competency${"schema_version":3,"relevant_when":"Andre er usikre på hva du mener, hvorfor noe er viktig eller hva som forventes; budskapet blir tolket ulikt; du gir mye informasjon uten at det skaper klarhet.","distinction":"Velg Påvirkning når budskapet forstås, men oppslutningen mangler. Velg Tydelig ledertilstedeværelse når innholdet er godt, men fremføringen svekker trygghet eller oppmerksomhet.","best_practice":{"success":["Når du starter med hensikt, hovedbudskap og ønsket neste steg.","Når du tilpasser språk, detaljnivå og kanal til mottaker og situasjon.","Når du lytter, undersøker reaksjoner og kontrollerer faktisk forståelse."],"underuse":["Når du gjør budskapet uklart, ustrukturert eller vanskelig å omsette i handling.","Når du antar at andre har samme kontekst eller har forstått uten å sjekke.","Når du lytter mest for å svare, ikke for å forstå."],"overuse":["Når du overforklarer slik at hovedpoenget forsvinner.","Når du gir så mye detalj at andres handlingsrom blir mindre.","Når du tilpasser budskapet så mye at konsistens eller tydelighet svekkes."]},"barriers":["Du antar at andre vet det du vet.","Du går raskt til løsning før du har forstått den andres perspektiv.","Du unngår tydelighet når budskapet kan skape motstand."],"practice":{"effect":"Færre oppklaringsrunder og mer samsvar i det deltakerne oppfatter.","experiment":"I tre viktige møter: innled med hovedbudskapet i én setning og be en mottaker oppsummere beslutning og neste steg."},"reflection":[]}$competency$::jsonb),
    ('pavirkning', 'Påvirkning', 'Influence', 'foundation', 'Skaper oppslutning ved å forstå interesser, bygge troverdighet og tilpasse påvirkningsformen uten å lene seg bare på formell autoritet.', $competency${"schema_version":3,"relevant_when":"Gode forslag får lite gjennomslag; viktige interessenter kommer sent inn; du argumenterer mer når andre er skeptiske.","distinction":"Velg Kommunikasjon når problemet først og fremst er forståelse. Velg Organisasjonsforståelse når du ikke vet hvem eller hva som faktisk påvirker beslutningen. Velg Forhandling når partene må bytte verdi og inngå en konkret avtale.","best_practice":{"success":["Når du kartlegger interesser, bekymringer og beslutningskriterier før saken presenteres.","Når du bruker relasjon, logikk, involvering og formål situasjonstilpasset.","Når du bygger støtte før formelle beslutningsøyeblikk."],"underuse":["Når du presenterer et godt argument og forventer at kvaliteten alene skal skape oppslutning.","Når du undervurderer relasjoner, interesser eller beslutningsdynamikk.","Når du unngår å be eksplisitt om støtte."],"overuse":["Når du fortsetter å presse etter at motstand gir viktig informasjon.","Når du lar tilpasning bli manipulasjon eller gjør egen posisjon uklar.","Når du lar det å vinne bli viktigere enn reell dialog."]},"barriers":["Du tror et godt argument bør være nok.","Du bruker samme påvirkningsform med ulike mennesker.","Du blir defensiv når argumentasjonen din utfordres."],"practice":{"effect":"Interessentene bidrar tidligere, og motforestillinger blir kjent før beslutningsmøtet.","experiment":"Kartlegg tre nøkkelinteressenter i én sak, test forståelsen av deres interesser og tilpass inngangen."},"reflection":[]}$competency$::jsonb),
    ('laeringssmidighet', 'Læringssmidighet', 'Learning Agility', 'foundation', 'Trekker læring ut av erfaring og bruker den fleksibelt i nye, krevende eller uklare situasjoner.', $competency${"schema_version":3,"relevant_when":"Tidligere styrker ikke lenger gir samme effekt; du gjentar mønstre etter tilbakeslag; en ny rolle krever at du lærer raskere enn du kan planlegge.","distinction":"Velg Egenutvikling når utfordringen er å prioritere og følge opp en langsiktig utviklingsplan. Velg Tilpasse seg endring når den primære utfordringen er reaksjonen på en konkret endring.","best_practice":{"success":["Når du oppsøker erfaringer som utfordrer egne antakelser og vaner.","Når du reflekterer systematisk over både gode og svake resultater.","Når du prøver ny atferd og overfører læring mellom situasjoner."],"underuse":["Når du gjentar kjente løsninger selv om situasjonen har endret seg.","Når du samler erfaringer uten å trekke ut tydelig læring.","Når du unngår oppgaver hvor du ikke allerede vet hvordan du skal lykkes."],"overuse":["Når du søker nytt uten å bli lenge nok til å høste læringen.","Når du endrer tilnærming før den har fått rimelig tid til å virke.","Når du lar refleksjon og utforskning erstatte beslutning og gjennomføring."]},"barriers":["Du holder fast ved det som tidligere har gjort deg vellykket.","Du forklarer motgang primært med forhold utenfor deg selv.","Du går raskt videre uten å undersøke hva erfaringen lærte deg."],"practice":{"effect":"Minst én konkret endring blir prøvd i neste sammenlignbare situasjon.","experiment":"Gjennomfør en kort etteranalyse etter tre krevende hendelser: forventning, faktisk resultat, forklaring og neste forsøk."},"reflection":["Hvilken nylig erfaring utfordret en måte å lede på som tidligere har virket godt?"]}$competency$::jsonb),
    ('selvinnsikt', 'Selvinnsikt', 'Self-Awareness', 'foundation', 'Forstår egne mønstre, drivere, styrker, begrensninger og virkningen egen atferd har på andre.', $competency${"schema_version":3,"relevant_when":"Du får overraskende eller gjentakende feedback; intensjonen din og andres opplevelse spriker; bestemte situasjoner utløser lite hensiktsmessige reaksjoner.","distinction":"Selvinnsikt er ofte en forutsetning for andre mål, men bør bare velges som primær kompetanse når manglende forståelse av egne mønstre er selve flaskehalsen.","best_practice":{"success":["Når du har et realistisk bilde av styrker, begrensninger og ledervirkning.","Når du gjenkjenner triggere og automatiske reaksjonsmønstre.","Når du søker og tåler informasjon som utfordrer selvbildet."],"underuse":["Når du lar forskjellen mellom eget selvbilde og andres erfaring av deg bli stor.","Når du gjentar de samme reaksjonsmønstrene uten å undersøke dem.","Når du avviser eller forklarer bort tilbakemeldinger som utfordrer selvbildet ditt."],"overuse":["Når du lar selvrefleksjon bli overdreven selvovervåking.","Når du lar andres vurderinger få større vekt enn egne verdier og vurderinger.","Når du lar svakheter få så mye oppmerksomhet at reelle styrker underutnyttes."]},"barriers":["Du vurderer egen atferd ut fra intensjonen mer enn effekten.","Du søker mest tilbakemelding fra mennesker som kjenner deg godt.","Du ser lettere andres bidrag til problemer enn ditt eget."],"practice":{"effect":"Du kan formulere ett mønster og teste en alternativ respons i en reell situasjon.","experiment":"Be tre personer beskrive én situasjon der du virker på ditt beste og én der effekten blir svakere."},"reflection":["Er manglende innsikt i eget mønster selve flaskehalsen, eller en støtte for et mer konkret utviklingsmål?"]}$competency$::jsonb),
    ('baerekraftig-kapasitet', 'Bærekraftig kapasitet og prioritering', 'Balance', 'self_capacity', 'Forvalter krav, grenser og energi slik at viktige forpliktelser kan ivaretas med kvalitet over tid.', $competency${"schema_version":3,"relevant_when":"Belastningen er vedvarende; alt oppleves like viktig; arbeidspress svekker dømmekraft, relasjoner eller restitusjon.","distinction":"Velg Tidsstyring når kalender, arbeidsflyt og prioriteringspraksis er hovedproblemet. Velg Motstandskraft når utfordringen er å fungere og hente seg inn under belastning eller etter tilbakeslag.","best_practice":{"success":["Når du prioriterer eksplisitt mellom konkurrerende krav.","Når du setter grenser og beskytter nødvendig restitusjon.","Når du justerer belastning før kapasiteten er vesentlig svekket."],"underuse":["Når du systematisk lar kortsiktige krav fortrenge restitusjon og viktige forpliktelser.","Når du sier ja uten å vurdere kapasitet eller konsekvenser.","Når du lar vedvarende belastning svekke beslutningskvalitet eller relasjoner."],"overuse":["Når du lar hensynet til balanse bli en begrunnelse for å unngå nødvendige perioder med høy innsats.","Når du lar grensene bli så rigide at du mister fleksibilitet.","Når du prioriterer egen komfort foran legitimt lederansvar."]},"barriers":["Du kobler verdi til hvor mye du rekker.","Du har vanskelig for å si nei eller reforhandle forventninger.","Du oppdager belastning først når kapasiteten allerede er brukt opp."],"practice":{"effect":"Mer beskyttet tid til kjernearbeid og en merkbar reduksjon i uplanlagt overtid.","experiment":"Gjennomgå de neste fire ukene mot tre viktigste forpliktelser og fjern, flytt eller deleger minst to aktiviteter."},"reflection":[]}$competency$::jsonb),
    ('grensekryssende-samarbeid', 'Grensekryssende samarbeid', 'Boundary Spanning', 'relationships_influence', 'Skaper felles forståelse, tillit og handling på tvers av organisatoriske, faglige, geografiske eller sosiale grenser.', $competency${"schema_version":3,"relevant_when":"Siloer, ulike profesjoner eller enheter hindrer en felles leveranse; kunnskap og ressurser forblir adskilt; lokale mål konkurrerer.","distinction":"Velg Relasjonsledelse for en bredere, løpende relasjonsevne. Velg Strategisk samordning når hovedproblemet er at mål, ressurser og prioriteringer ikke peker samme vei.","best_practice":{"success":["Når du bygger trygghet og relasjon mellom grupper før konflikten tilspisser seg.","Når du finner felles interesser uten å skjule reelle forskjeller.","Når du skaper nye koblinger mellom mennesker, kunnskap og ressurser."],"underuse":["Når du prioriterer egen enhet uten å håndtere avhengigheter.","Når du lar viktig informasjon og kompetanse bli værende i siloer.","Når du kontakter andre først når du trenger noe."],"overuse":["Når du involverer så bredt at ansvar og tempo blir uklart.","Når du lar nettverksbygging erstatte beslutninger i egen linje.","Når du lar kompromiss bli viktigere enn tydelig prioritering."]},"barriers":["Du undervurderer hvor avhengig egen enhet er av andre.","Du opplever andre enheters prioriteringer som hindringer mer enn legitime hensyn.","Du bygger relasjoner for sent."],"practice":{"effect":"Et konkret informasjons- eller arbeidsbrudd blir redusert.","experiment":"Velg én kritisk grense og samle partene om felles leveranse, avhengigheter og én gjensidig forpliktelse."},"reflection":[]}$competency$::jsonb),
    ('forretningsutvikling', 'Forretningsutvikling', 'Business Development', 'strategy_business_change', 'Oppdager og utvikler muligheter som kobler reelle behov med virksomhetens evne til å skape varig verdi.', $competency${"schema_version":3,"relevant_when":"Rollen har ansvar for vekst, nye tjenester, markeder eller verdiforslag; dagens leveranser tar all oppmerksomhet; kundesignaler omsettes sjelden til nye muligheter.","distinction":"Velg Innovasjon når utfordringen er å realisere nye løsninger bredere enn kommersiell vekst. Velg Forretnings- og fagforståelse når kunnskapsgrunnlaget, ikke mulighetsutviklingen, er flaskehalsen.","best_practice":{"success":["Når du utforsker behov og endringer uten å starte med egen løsning.","Når du kobler muligheter til virksomhetens evne til å levere og skape lønnsomhet.","Når du tester antakelser før større investeringer."],"underuse":["Når du reagerer på etterspørsel, men sjelden skaper nye muligheter.","Når du lar ideer bli værende uten tydelige hypoteser, kundeinnsikt eller handling.","Når du mangler kommersiell oppfølging av gode relasjoner."],"overuse":["Når du forfølger vekstmuligheter uten strategisk samsvar eller lønnsomhet.","Når du lar salgshensyn overskygge leveranseevne eller kundeverdi.","Når du starter flere initiativer enn organisasjonen kan følge opp."]},"barriers":["Du venter på sikre bevis før du tester en mulighet.","Du synes kommersielle samtaler er mindre naturlige enn faglige.","Du forelsker deg i løsningen før behovet er testet."],"practice":{"effect":"Minst én sentral antakelse blir bekreftet, avkreftet eller vesentlig presisert.","experiment":"Gjennomfør fem utforskende samtaler om ett behov og formuler en testbar verdihypotese."},"reflection":[]}$competency$::jsonb),
    ('forretnings-og-fagforstaelse', 'Forretnings- og fagforståelse', 'Business and Professional Knowledge', 'strategy_business_change', 'Bruker relevant fagkunnskap og forståelse av virksomhetens økonomiske og operative logikk i beslutninger.', $competency${"schema_version":3,"relevant_when":"Beslutninger tas med for smalt funksjonsperspektiv; rollen har vokst raskere enn forretningsforståelsen; fagkunnskap eller markedsinnsikt er blitt utdatert.","distinction":"Velg Organisasjonsforståelse når du forstår virksomheten, men ikke hvordan beslutninger og innflytelse faktisk fungerer. Velg Globalt perspektiv når utfordringen gjelder markeder, kulturer og internasjonale avhengigheter.","best_practice":{"success":["Når du holder kritisk fag- og markedsinnsikt oppdatert.","Når du forstår økonomiske, operative og kundemessige drivere.","Når du kobler eget fagområde til virksomheten som helhet."],"underuse":["Når du tar beslutninger uten tilstrekkelig forståelse av fag, marked eller økonomi.","Når du ikke holder deg oppdatert på endringer som påvirker ansvarsområdet.","Når du har vanskelig for å oversette fagkunnskap til forretningsmessige konsekvenser."],"overuse":["Når du lar ekspertise bli identitet og gjør deg mindre åpen for andre perspektiver.","Når du går for langt ned i faglige detaljer som andre bør eie.","Når du bruker kunnskap til å dominere fremfor å opplyse beslutningen."]},"barriers":["Du stoler på erfaring som ikke lenger er oppdatert.","Du lærer mest innen eget fag og for lite om virksomheten rundt.","Du går lett inn i ekspertrollen når du burde lede."],"practice":{"effect":"Du identifiserer minst én avhengighet eller konsekvens du tidligere overså.","experiment":"Følg én leveranse på tvers av kunde, drift og økonomi, og forklar verdiskapingen tilbake til en kollega."},"reflection":[]}$competency$::jsonb),
    ('mobilisere-for-endring', 'Mobilisere for endring', 'Champion Change', 'strategy_business_change', 'Skaper forståelse, energi og oppslutning rundt hvorfor en endring er nødvendig og verdt å bidra til.', $competency${"schema_version":3,"relevant_when":"Endringen har en plan, men lav støtte; behovet oppleves uklart; ledere kommuniserer endringen uten selv å modellere den.","distinction":"Velg Gjennomføre endring når oppslutningen finnes, men ny praksis ikke fester seg. Velg Tilpasse seg endring når det er din egen respons på endring som er utviklingsbehovet.","best_practice":{"success":["Når du forklarer behov, retning og konsekvenser ærlig.","Når du anerkjenner tap, motstand og legitime bekymringer.","Når du viser endringen gjennom egne valg og mobiliserer troverdige støttespillere."],"underuse":["Når du kommuniserer hva som skal endres uten å skape mening eller eierskap.","Når du tolker motstand som negativitet i stedet for informasjon.","Når du støtter endringen i ord, men ikke i egne prioriteringer."],"overuse":["Når du fremstiller endring som mål i seg selv.","Når du presser tempo uten å ta hensyn til kapasitet og konsekvenser.","Når du lar optimisme gjøre at reelle tap, risikoer eller innvendinger bagatelliseres."]},"barriers":["Du antar at andre ser behovet like tydelig som deg.","Du blir utålmodig med mennesker som trenger mer tid.","Du kommuniserer løsning før problemet er felles forstått."],"practice":{"effect":"Du kan gjengi deres tap og bekymringer og justere minst ett element i tilnærmingen.","experiment":"Test endringsfortellingen med én støttespiller, én usikker og én skeptiker før bred kommunikasjon."},"reflection":[]}$competency$::jsonb),
    ('tilpasse-seg-endring', 'Tilpasse seg endring', 'Change Acceptance', 'self_capacity', 'Møter endrede rammer konstruktivt, bearbeider egen reaksjon og justerer praksis når situasjonen krever det.', $competency${"schema_version":3,"relevant_when":"Du holder fast ved tidligere løsninger, bruker mye energi på det som ikke kan reverseres eller reagerer defensivt på endrede rammer.","distinction":"Velg Fleksibilitet når behovet er å variere stil eller arbeidsmåte i en løpende situasjon. Velg Navigere i usikkerhet når problemet er manglende informasjon, ikke endringen i seg selv.","best_practice":{"success":["Når du gjenkjenner og bearbeider egen første reaksjon.","Når du skiller legitim kritikk fra motstand mot å gi slipp.","Når du tester ny praksis og justerer ut fra erfaring."],"underuse":["Når du holder fast ved tidligere løsninger etter at premissene er endret.","Når du lar usikkerhet føre til passivitet, kynisme eller langvarig motstand.","Når du venter på full klarhet før du begynner å tilpasse deg."],"overuse":["Når du aksepterer endringer ukritisk og unnlater å løfte reell risiko.","Når du lar tilpasning bli opportunisme uten tydelige prinsipper.","Når du går videre så raskt at andre ikke får bearbeidet konsekvensene."]},"barriers":["Du tolker tap av kontroll som tegn på at endringen er dårlig.","Du trenger mer sikkerhet enn situasjonen kan gi.","Du romantiserer hvordan ting fungerte før."],"practice":{"effect":"Vurderingen blir basert på erfaring fremfor første reaksjon.","experiment":"Velg én endring du misliker, noter hva som faktisk er fast og påvirkbart, og test én ny arbeidsmåte i to uker."},"reflection":[]}$competency$::jsonb),
    ('endringsledelse', 'Gjennomføre endring', 'Change Implementation', 'strategy_business_change', 'Omsetter endringsretning til ny atferd, arbeidspraksis, struktur og oppfølging som varer.', $competency${"schema_version":3,"relevant_when":"Endringen stopper ved presentasjoner og planer; ansvar og ønsket atferd er uklart; ny praksis brukes bare sporadisk.","distinction":"Velg Mobilisere for endring når forståelse og oppslutning mangler. Velg Strategisk planlegging og gjennomføring for en bredere portefølje av strategiske initiativer.","best_practice":{"success":["Når du oversetter mål til konkret atferd, ansvar og milepæler.","Når du fjerner strukturelle og praktiske hindringer.","Når du måler faktisk bruk og effekt, ikke bare aktivitet."],"underuse":["Når du lar endringen stoppe etter kommunikasjon eller lansering.","Når du ikke avklarer ansvar, avhengigheter eller nye arbeidsmåter.","Når du måler aktivitet, men ikke om ny praksis faktisk tas i bruk."],"overuse":["Når du lar implementeringen bli så rigid at læring underveis ikke får påvirke planen.","Når du lar oppfølging bli kontroll fremfor støtte.","Når du prioriterer tempo foran at ny praksis faktisk tas i bruk."]},"barriers":["Du undervurderer hvor mye oppfølging atferdsendring krever.","Du antar at beslutning betyr gjennomføring.","Du fokuserer mer på prosjektplanen enn på hva mennesker faktisk gjør."],"practice":{"effect":"Andelen som faktisk bruker ny praksis øker.","experiment":"Definer tre observerbare atferder og én strukturell forutsetning for en aktuell endring; følg opp etter 30 dager."},"reflection":[]}$competency$::jsonb),
    ('utvikle-andre', 'Utvikle andre', 'Coach and Develop Others', 'team_people', 'Hjelper andre å bygge kapasitet gjennom refleksjon, utfordrende erfaringer, støtte og ansvar.', $competency${"schema_version":3,"relevant_when":"Du løser problemer for andre; medarbeidere får lite strekk eller utviklingsretning; levering vinner over læring hver gang.","distinction":"Velg Feedback når behovet primært er å gjøre virkningen av konkret atferd tydelig. Velg Delegering når problemet er overføring av ansvar og mandat.","best_practice":{"success":["Når du tilpasser utvikling til person, rolle og situasjon.","Når du stiller spørsmål som fremmer refleksjon og eierskap.","Når du kombinerer utfordrende oppgaver med relevant støtte og oppfølging."],"underuse":["Når du løser problemer for andre i stedet for å utvikle deres evne til å løse dem.","Når du lar utviklingssamtaler bli generelle eller sjeldne.","Når du ser potensial uten å gi reelle muligheter eller ansvar."],"overuse":["Når du gjør alle situasjoner til coaching selv når tydelig instruksjon trengs.","Når du lar utviklingshensyn overskygge leveransekrav.","Når du presser mennesker inn i utfordringer de ikke er klare for."]},"barriers":["Du får energi av å være den som har svaret.","Du prioriterer leveransen foran læringen hver gang.","Du gir mer støtte til dem du kjenner deg igjen i."],"practice":{"effect":"Medarbeideren formulerer mer av problemet og løsningen selv.","experiment":"I fire samtaler: still tre utforskende spørsmål før du gir råd, og avtal ett selvvalgt neste steg."},"reflection":[]}$competency$::jsonb),
    ('empati-og-omtanke', 'Empati og omtanke', 'Compassion and Sensitivity', 'relationships_influence', 'Forstår hvordan andre opplever en situasjon og møter behov, reaksjoner og belastninger med respekt uten å oppheve ansvar.', $competency${"schema_version":3,"relevant_when":"Du går raskt til løsning; andre opplever deg som lite tilgjengelig eller hard; viktige menneskelige konsekvenser kommer sent inn i vurderingene.","distinction":"Velg Mellommenneskelig teft når behovet er å lese og tilpasse samspillet bredere. Velg Bygge tillit når relasjonens forutsigbarhet og trygghet er hovedproblemet.","best_practice":{"success":["Når du undersøker andres perspektiv før vurdering eller løsning.","Når du anerkjenner følelser og konsekvenser uten å overta ansvaret.","Når du kombinerer omtanke med tydelige og rettferdige forventninger."],"underuse":["Når du overser emosjonelle eller relasjonelle konsekvenser av beslutninger.","Når du går rett til løsning før personen opplever seg forstått.","Når du først registrerer behov etter at andre sier dem helt eksplisitt."],"overuse":["Når du lar empati gjøre at du unngår nødvendige krav eller vanskelige beslutninger.","Når du tar for mye ansvar for andres følelser.","Når du lar sensitivitet bli overtolkning av signaler."]},"barriers":["Du blir ukomfortabel når samtaler blir emosjonelle.","Du tror saklighet betyr at følelser bør holdes utenfor.","Du forveksler omtanke med å gjøre situasjonen lettere."],"practice":{"effect":"Den andre korrigerer eller bekrefter forståelsen og deltar mer aktivt i neste steg.","experiment":"I en krevende samtale: oppsummer den andres perspektiv og spør om du har forstått før du foreslår løsning."},"reflection":[]}$competency$::jsonb),
    ('konflikthandtering', 'Konflikthåndtering', 'Conflict Resolution', 'relationships_influence', 'Tar tak i uenighet tidlig, reduserer personangrep og bruker forskjeller til å avklare interesser og finne en farbar vei videre.', $competency${"schema_version":3,"relevant_when":"Uenighet unngås eller blir personlig; de samme konfliktene gjentar seg; harmoni prioriteres foran nødvendig avklaring.","distinction":"Velg Forhandling når partene primært skal inngå en avtale om knappe goder eller forpliktelser. Velg Håndtere prestasjons- og atferdsutfordringer når en leder må følge opp brudd på forventet standard.","best_practice":{"success":["Når du tar opp saken tidlig og skiller person, atferd, posisjon og interesse.","Når du roer ned samspillet uten å fjerne den reelle uenigheten.","Når du avklarer ansvar og løsning partene faktisk kan stå i."],"underuse":["Når du unngår konflikten til den blir personlig eller fastlåst.","Når du glatter over reell uenighet for å bevare harmoni.","Når du lar uklare avtaler gjøre at samme konflikt kommer tilbake."],"overuse":["Når du gjør enhver uenighet til en prosess som må bearbeides.","Når du bruker direkte konfrontasjon før partene er klare for den.","Når du presser frem enighet der legitim forskjell bør bestå."]},"barriers":["Du forbinder konflikt med dårlig samarbeid.","Du venter på at problemet skal gå over av seg selv.","Du tar parti før du har forstått begge perspektiver."],"practice":{"effect":"Partene kan beskrive uenigheten uten å tillegge hverandre motiv.","experiment":"Ta opp én mindre uenighet tidligere enn vanlig og oppsummer begge parters interesser før løsningsforslag."},"reflection":[]}$competency$::jsonb),
    ('prestasjons-og-atferdsutfordringer', 'Håndtere prestasjons- og atferdsutfordringer', 'Confronting Problem Employees', 'team_people', 'Følger tydelig, rettferdig og rettidig opp prestasjon eller atferd som ikke møter avtalte krav.', $competency${"schema_version":3,"relevant_when":"Problemer får vare; forventninger formidles indirekte; teamet bærer kostnaden ved manglende oppfølging.","distinction":"Velg Feedback for løpende korrigering og læring. Denne kompetansen gjelder vedvarende eller vesentlige avvik som krever tydelig ledelsesoppfølging.","best_practice":{"success":["Når du undersøker forventning, kapasitet, ressurser, system og atferd før konklusjon.","Når du beskriver fakta, effekt, krav og støtte tydelig.","Når du dokumenterer avtaler og følger opp på et bestemt tidspunkt."],"underuse":["Når du lar problemer få vedvare fordi samtalen er ubehagelig.","Når du lar tilbakemeldingen bli vag og personen ikke forstår alvoret.","Når du lar kolleger kompensere fordi du ikke følger opp."],"overuse":["Når du behandler enkelthendelser som varige prestasjonsproblemer.","Når du lar konfrontasjon bli straffende eller personlig.","Når du går til konsekvenser før forventninger og støtte har vært tydelige."]},"barriers":["Du håper problemet retter seg uten at du må ta samtalen.","Du er redd for å skade relasjonen.","Du samler opp irritasjon og blir for hard når du først tar det opp."],"practice":{"effect":"Begge parter kan gjengi hva som må endres, hvilken støtte som gis og hvordan fremgang vurderes.","experiment":"Forbered én samtale med observerbare fakta, forventet standard, mulige systemforhold og dato for oppfølging."},"reflection":[]}$competency$::jsonb),
    ('mot', 'Mot', 'Courage', 'self_capacity', 'Sier fra og handler i tråd med faglige eller etiske vurderinger når det innebærer reell sosial, personlig eller organisatorisk risiko.', $competency${"schema_version":3,"relevant_when":"Du holder tilbake viktig informasjon, utsetter vanskelige samtaler eller lar hensynet til egen trygghet dominere.","distinction":"Velg Risikovilje når usikkerheten primært gjelder resultat eller investering. Velg Initiativ når utfordringen er å starte uten å bli bedt, ikke å tåle personlig risiko.","best_practice":{"success":["Når du synliggjør risikoen og handler etter en bevisst vurdering.","Når du tar opp vanskelige saker med tydelighet og respekt.","Når du står for prinsipper uten å gjøre motstand til identitet."],"underuse":["Når du tier selv om viktig informasjon eller uenighet bør frem.","Når du utsetter beslutninger primært for å unngå personlig risiko.","Når du lar hierarki eller gruppetrykk overstyre faglig vurdering."],"overuse":["Når du lar modighet bli unødvendig konfrontasjon eller risikosøking.","Når du står fast på et standpunkt etter at ny informasjon tilsier endring.","Når du lar det å være tydelig bli viktigere enn å være klok."]},"barriers":["Du overvurderer den personlige kostnaden ved å si fra.","Du ønsker å være sikker før du tar standpunkt.","Du forveksler harmoni med godt samarbeid."],"practice":{"effect":"Saken blir reelt behandlet uten at respekten i relasjonen bryter sammen.","experiment":"Velg én sak du har holdt tilbake, avklar risiko og formuler budskap, hensikt og ønsket dialog før du tar den opp."},"reflection":[]}$competency$::jsonb),
    ('kreativitet', 'Kreativitet', 'Creativity', 'execution_decisions', 'Utvikler flere og mer originale muligheter ved å utfordre antakelser og kombinere perspektiver.', $competency${"schema_version":3,"relevant_when":"Teamet hopper til første løsning; alternativer ligner hverandre; etablerte antakelser snevrer inn handlingsrommet.","distinction":"Velg Innovasjon når ideene finnes, men ikke blir testet eller realisert. Velg Problemløsning når hovedbehovet er å forstå årsak og velge en robust løsning.","best_practice":{"success":["Når du skiller idéskaping fra evaluering.","Når du henter perspektiver som bryter med det etablerte.","Når du utforsker flere problemformuleringer og løsningsretninger."],"underuse":["Når du går til første plausible løsning.","Når du behandler etablerte arbeidsmåter som premisser i stedet for valg.","Når du avgrenser idéarbeidet til det som allerede virker realistisk."],"overuse":["Når du fortsetter idéarbeidet etter at situasjonen krever et valg.","Når du lar originalitet bli viktigere enn nytte.","Når du lar stadig nye ideer skape ustabilitet i gjennomføringen."]},"barriers":["Du vurderer ideer før de er utviklet.","Du søker raskt etter beste praksis i stedet for alternative perspektiver.","Du trives bedre med forbedring enn med å utfordre premisset."],"practice":{"effect":"Minst ett levedyktig alternativ bryter tydelig med den opprinnelige løsningsretningen.","experiment":"Generer minst ti alternativer med to personer utenfor fagområdet før kriterier brukes."},"reflection":[]}$competency$::jsonb),
    ('troverdighet-og-integritet', 'Troverdighet og integritet', 'Credibility and Integrity', 'foundation', 'Handler konsistent med uttalte verdier og forpliktelser, også når åpenhet eller prinsippfasthet har en kostnad.', $competency${"schema_version":3,"relevant_when":"Det er avstand mellom ord og handling; du lover mer enn du følger opp; vurderingsgrunnlag eller feil skjules.","distinction":"Velg Bygge tillit når utviklingsbehovet gjelder den bredere, gjensidige relasjonen. Integritet er et sentralt grunnlag for tillit, men tillit påvirkes også av kompetanse, omtanke og forutsigbarhet.","best_practice":{"success":["Når du holder eller reforhandler forpliktelser før de brytes.","Når du forklarer vurderinger, usikkerhet og interessekonflikter åpent.","Når du handler i tråd med prinsipper under press."],"underuse":["Når du lar løfter, forventninger eller begrunnelser bli uklare.","Når du sier ulike ting til ulike grupper uten saklig grunn.","Når du lar kortsiktig gevinst få overstyre prinsipper eller langsiktig tillit."],"overuse":["Når du lar prinsippfasthet bli rigiditet uten hensyn til kontekst.","Når du deler informasjon som åpenhet, selv om den bør beskyttes.","Når du bruker moralsk tydelighet til å dømme mennesker fremfor handlinger."]},"barriers":["Du lover mer enn du kan kontrollere.","Du undervurderer hvor mye små inkonsistenser påvirker tillit.","Du blir defensiv når egne valg utfordres."],"practice":{"effect":"Berørte parter vet hva de kan forvente og hvorfor.","experiment":"Lukk eller reforhandle én uavklart forpliktelse og forklar én krevende beslutning med kriterier og usikkerhet."},"reflection":[]}$competency$::jsonb),
    ('beslutningstaking', 'Beslutningstaking', 'Decision Making', 'execution_decisions', 'Velger og forplikter seg til en retning på riktig tidspunkt, med relevant informasjon, tydelige kriterier og passende involvering.', $competency${"schema_version":3,"relevant_when":"Beslutninger tas for sent, for tidlig eller med uklar beslutningseier; konsensus blir standard; alternativer vurderes uten kriterier.","distinction":"Velg Problemløsning når problemforståelsen og analysen er svak. Velg Navigere i usikkerhet når ubehaget ved manglende informasjon hindrer funksjon bredere enn selve beslutningen.","best_practice":{"success":["Når du avklarer beslutning, eier, kriterier og frist.","Når du involverer dem som øker kvalitet eller er nødvendige for gjennomføring.","Når du beslutter med eksplisitte antakelser når informasjonen er ufullstendig."],"underuse":["Når du utsetter valg i påvente av informasjon som neppe endrer beslutningen.","Når du tar beslutninger uten å avklare kriterier eller konsekvenser.","Når du lar saker bli stående uten en tydelig beslutningseier."],"overuse":["Når du lar tempo bli viktigere enn tilstrekkelig analyse.","Når du bestemmer før relevante perspektiver er hørt.","Når du låser deg til eget valg og forsvarer det etter at premissene endres."]},"barriers":["Du søker sikkerhet der situasjonen bare kan gi sannsynlighet.","Du blander diskusjon, analyse og beslutning.","Du opplever omgjøring som et tegn på svakhet."],"practice":{"effect":"Beslutningen tas innen fristen og kan etterprøves uten å rekonstruere prosessen.","experiment":"Bruk et beslutningsnotat med spørsmål, kriterier, alternativer, antakelser, eier og frist på én aktuell sak."},"reflection":[]}$competency$::jsonb),
    ('delegering', 'Delegering', 'Delegating', 'team_people', 'Overfører et avgrenset ansvar med tydelig resultat, mandat, rammer og oppfølging.', $competency${"schema_version":3,"relevant_when":"Du gjør arbeid andre kan eie; oppgaver delegeres uten myndighet; du tar arbeidet tilbake ved første problem.","distinction":"Velg Lede gjennom andre når hele organiseringen av arbeid og beslutninger gjør deg til flaskehals. Delegering gjelder en konkret overføring; ledelse gjennom andre gjelder systemet rundt flere leveranser.","best_practice":{"success":["Når du delegerer ansvar som gir andre reelt eierskap til resultatet.","Når du gjør ønsket resultat, kvalitetskrav og forventninger tydelige.","Når du gir nødvendig kontekst om oppgaven, interessenter, ressurser og mulige hindringer.","Når du avklarer roller, mandat og hvilke beslutninger den andre kan ta selv.","Når du tilpasser ansvar og støtte til den enkeltes erfaring og kompetanse.","Når du avtaler hvordan og når du skal følge opp, uten å detaljstyre.","Når du lar andre finne sin egen vei til resultatet og forsøke å løse problemer før du griper inn.","Når du øker ansvar og handlingsrom etter hvert som den andre mestrer mer.","Når du bruker delegering til å utvikle medarbeidernes kompetanse og selvstendighet.","Når du avslutter delegerte oppgaver med tilbakemelding og refleksjon over hva som er lært."],"underuse":["Når du holder på ansvar som andre kunne tatt.","Når du undervurderer hva medarbeiderne dine kan håndtere.","Når du delegerer oppgaver, men beholder beslutningsmyndigheten selv.","Når du involverer deg i detaljer den andre kunne håndtert.","Når du griper inn så snart det oppstår problemer.","Når du forventer at andre skal løse oppgaven på samme måte som du ville gjort.","Når du lar andre bli avhengige av deg for å komme videre.","Når du blir en flaskehals fordi for mange beslutninger og leveranser må gjennom deg."],"overuse":["Når du gir andre mer ansvar enn de har forutsetninger for å håndtere.","Når du overvurderer kompetansen deres og gir mindre støtte enn de trenger.","Når du delegerer uten å gjøre resultat, kvalitetskrav eller rammer tydelige.","Når du gir ansvar uten nødvendig myndighet eller ressurser.","Når du forventer selvstendighet før den andre er klar for det.","Når du følger opp så lite at problemer eller avvik oppdages for sent.","Når du bruker delegering til å skyve fra deg arbeid eller beslutninger du selv bør eie.","Når du delegerer gjennomføringen og samtidig fraskriver deg ansvaret for resultatet."]},"barriers":["Du er usikker på om andre vil levere med den kvaliteten du forventer.","Du har tidligere delegert ansvar og blitt skuffet over resultatet.","Du synes det er vanskelig å gi fra deg kontroll.","Du tenker at det går raskere eller blir bedre hvis du gjør arbeidet selv.","Du har for lite innsikt i hva medarbeiderne dine er klare for å eie.","Du er usikker på hvor mye ansvar eller støtte den enkelte trenger.","Du får mestring, synlighet eller anerkjennelse gjennom arbeid du egentlig kunne gitt videre.","Du synes det er vanskelig å akseptere at andre løser oppgaver på en annen måte enn deg."],"practice":{"effect":"Den andre tar selvstendige beslutninger innenfor mandatet, og du griper ikke inn mellom milepælene.","experiment":"Deleger én viktig leveranse med skriftlig avklaring av resultat, mandat, rammer og to milepæler."},"reflection":["Hvor blir du selv en flaskehals?","Når du følger opp: hjelper du den andre videre, eller tar du i praksis arbeidet tilbake?"]}$competency$::jsonb),
    ('inkluderende-ledelse', 'Inkluderende ledelse', 'Difference, Diversity, Inclusion', 'relationships_influence', 'Skaper beslutnings- og samarbeidsprosesser hvor ulike erfaringer, perspektiver og identiteter får reell innflytelse.', $competency${"schema_version":3,"relevant_when":"De samme stemmene dominerer; representasjon finnes uten innflytelse; beslutninger overser systematiske forskjeller i vilkår eller konsekvenser.","distinction":"Velg Empati og omtanke når behovet først og fremst gjelder forståelse av enkeltmenneskers opplevelse. Inkluderende ledelse gjelder også strukturer, makt og beslutningsprosesser.","best_practice":{"success":["Når du undersøker hvem som er representert, hørt og faktisk påvirker.","Når du utfordrer egne og gruppens antakelser med relevante motperspektiver.","Når du endrer prosesser som systematisk gir noen mindre tilgang eller innflytelse."],"underuse":["Når du lar de samme stemmene systematisk få definere problem og løsning.","Når du tolererer forskjeller uten å bruke dem som ressurs.","Når du antar at lik behandling alltid gir like muligheter til å bidra."],"overuse":["Når du lar representasjon bli viktigere enn relevant kompetanse eller saklig vurdering.","Når du reduserer mennesker til gruppetilhørighet.","Når du lar frykt for å gjøre feil gjøre samtaler kunstige eller unnvikende."]},"barriers":["Du søker ubevisst mennesker som tenker og kommuniserer som deg.","Du tolker stillhet som enighet.","Du undervurderer hvordan etablerte normer favoriserer enkelte arbeidsmåter."],"practice":{"effect":"Flere relevante perspektiver påvirker beslutningen, ikke bare samtalen.","experiment":"Kartlegg taletid, forslag og påvirkning i tre møter, og endre én møtepraksis."},"reflection":[]}$competency$::jsonb),
    ('engasjement-og-eierskap', 'Skape engasjement og eierskap', 'Engagement', 'team_people', 'Former mening, autonomi, mestring og tilhørighet slik at mennesker ønsker og evner å bidra.', $competency${"schema_version":3,"relevant_when":"Innsatsen er mekanisk; eierskapet er lavt; medarbeidere ser liten sammenheng mellom oppgaver og det som betyr noe.","distinction":"Velg Lede med formål når utfordringen er den overordnede meningen og retningen. Velg Utvikle andre når læring og vekst er hovedbehovet.","best_practice":{"success":["Når du forstår hva som gir og tapper energi for ulike mennesker.","Når du kobler oppgaver til tydelig verdi og relevant helhet.","Når du gir reelt handlingsrom, mestringsstøtte og anerkjennelse."],"underuse":["Når du forventer motivasjon uten å skape klarhet, innflytelse eller mening.","Når du tar innsats for gitt og bidrag sjelden anerkjennes.","Når du venter med å håndtere frakobling til prestasjonen faller."],"overuse":["Når du prøver å gjøre alt inspirerende og unngår nødvendige, mindre attraktive oppgaver.","Når du forveksler engasjement med trivsel eller konstant entusiasme.","Når du tar for stort ansvar for motivasjon som også eies av den enkelte."]},"barriers":["Du antar at det som motiverer deg også motiverer andre.","Du fokuserer mer på oppgaver enn på betingelsene for eierskap.","Du bruker anerkjennelse generelt i stedet for konkret."],"practice":{"effect":"Medarbeideren tar mer initiativ eller rapporterer bedre sammenheng mellom ansvar og motivasjon.","experiment":"Spør hver medarbeider hva som gir energi, tapper energi og hvilket handlingsrom som vil hjelpe; endre ett forhold."},"reflection":[]}$competency$::jsonb),
    ('tydelig-ledertilstedevaerelse', 'Tydelig ledertilstedeværelse', 'Executive Image', 'relationships_influence', 'Formidler ro, klarhet, tilgjengelighet og troverdighet gjennom ord, tone og kroppsspråk når lederrollen er særlig synlig.', $competency${"schema_version":3,"relevant_when":"Kompetansen din kommer ikke tydelig frem; du blir for tilbaketrukket, urolig eller dominerende under press; fremføringen svekker budskapet.","distinction":"Velg Kommunikasjon når innhold, struktur eller mottakertilpasning er problemet. Målet her er ikke å ligne en stereotyp leder, men å øke samsvaret mellom hensikt, rolle og virkning.","best_practice":{"success":["Når du bevarer ro, kontakt og tydelighet under press.","Når du bruker stemme, tempo, pauser og kroppsspråk bevisst.","Når du tilpasser synlighet og autoritet uten å virke påtatt."],"underuse":["Når du lar nervøsitet, uklarhet eller uforberedt fremtoning svekke et ellers godt budskap.","Når du undervurderer hvordan tone, kroppsspråk og form påvirker tillit.","Når du blir for tilbakeholden i situasjoner hvor rollen krever synlighet."],"overuse":["Når du lar fremtoning bli iscenesettelse eller statusmarkering.","Når du fremstår sikrere enn kunnskapsgrunnlaget tilsier.","Når du lar kontrollert fremtoning gjøre deg mindre tilgjengelig eller autentisk."]},"barriers":["Du tror innholdet alene avgjør hvordan du blir vurdert.","Du fyller stillhet når du blir usikker.","Du prøver å se sikker ut i stedet for å være tydelig på hva du vet og ikke vet."],"practice":{"experiment":"Film én viktig presentasjon og be to personer gi konkret tilbakemelding på ro, klarhet og kontakt – ikke stilpreferanse.","effect":"Budskapet gjengis korrekt, og tilbakemeldingen viser mer trygghet uten at du virker mindre naturlig."},"reflection":[]}$competency$::jsonb),
    ('eksterne-partnerskap', 'Eksterne partnerskap', 'External Partnership Management', 'relationships_influence', 'Bygger og forvalter gjensidig verdiskapende relasjoner med eksterne aktører over tid.', $competency${"schema_version":3,"relevant_when":"Leveranser avhenger av kunder, leverandører, myndigheter eller partnere; relasjonen er transaksjonell; forventninger og avhengigheter er uklare.","distinction":"Velg Relasjonsledelse for relasjoner generelt. Eksterne partnerskap krever i tillegg tydelig styring av verdi, risiko, samarbeidsflater og organisatoriske interesser.","best_practice":{"success":["Når du forstår begge parters mål, begrensninger og alternativer.","Når du investerer i relasjonen før kritiske behov oppstår.","Når du avklarer forventninger, styring, risiko og gjensidige forpliktelser."],"underuse":["Når du styrer partnerskapet primært gjennom kontrakt eller enkeltleveranser.","Når du aktiverer relasjonen først når du trenger noe.","Når du lar uklare forventninger skape gjentatte misforståelser."],"overuse":["Når du lar relasjonshensyn gjøre at du aksepterer svak leveranse eller uklare vilkår.","Når du etablerer partnerskap uten tydelig strategisk verdi.","Når du deler mer informasjon eller kontroll enn samarbeidet krever."]},"barriers":["Du antar at felles mål betyr felles interesser.","Du prioriterer den operative leveransen og forsømmer relasjonen.","Du utsetter vanskelige avklaringer for å bevare god tone."],"practice":{"effect":"Partene dokumenterer minst én gjensidig forpliktelse eller korrigert antakelse.","experiment":"Gjennomfør en partnersamtale om mål, verdi, risiko og én uavklart forventning."},"reflection":[]}$competency$::jsonb),
    ('feedback', 'Feedback', 'Feedback', 'relationships_influence', 'Gir, innhenter og bruker konkret informasjon om atferd og virkning for å støtte læring og forbedring.', $competency${"schema_version":3,"relevant_when":"Tilbakemeldinger kommer sent eller generelt; mennesker blir overrasket over vurderinger; du får lite ærlig informasjon om egen virkning.","distinction":"Velg Utvikle andre for et bredere utviklingsansvar. Velg Håndtere prestasjons- og atferdsutfordringer ved vedvarende avvik som krever formell og tydelig oppfølging.","best_practice":{"success":["Når du beskriver tidsnær observasjon, virkning og ønsket retning.","Når du skiller data, tolkning og vurdering.","Når du ber om spesifikk feedback og viser hvordan den brukes."],"underuse":["Når du gir sjeldne eller generelle tilbakemeldinger, eller bare sier fra ved problemer.","Når du antar at mennesker forstår hvordan atferden deres virker.","Når du roser uten å si hva den andre bør gjenta."],"overuse":["Når du kommenterer så mye at mennesker blir selvbevisste eller avhengige av vurderingen din.","Når du korrigerer små avvik uten å vurdere betydningen.","Når du bruker direktehet uten tilstrekkelig omtanke for timing og relasjon."]},"barriers":["Du venter på den perfekte formuleringen.","Du gjør observasjoner om til tolkninger.","Du ber om tilbakemelding, men forsvarer deg når du får den."],"practice":{"effect":"Minst én observerbar atferd justeres, og den andre kan gjengi hva som var nyttig.","experiment":"Gi én konkret feedback og be om én konkret feedback hver uke i fire uker."},"reflection":[]}$competency$::jsonb),
    ('fleksibilitet', 'Fleksibilitet', 'Flexibility', 'self_capacity', 'Varierer tilnærming, lederstil og arbeidsform når mennesker, oppgaver eller situasjoner krever det, uten å miste målet.', $competency${"schema_version":3,"relevant_when":"Du bruker samme stil med alle; planen blir viktigere enn situasjonen; andre trenger en annen grad av støtte, involvering eller tydelighet.","distinction":"Velg Tilpasse seg endring når reaksjonen på endrede rammer er problemet. Velg Navigere i usikkerhet når du må fungere uten klare svar.","best_practice":{"success":["Når du leser hva oppgave, person og kontekst trenger.","Når du endrer virkemiddel samtidig som hensikt og rammer er tydelige.","Når du forklarer kursendringer slik at fleksibilitet ikke oppleves som vilkårlighet."],"underuse":["Når du holder fast ved plan eller arbeidsform etter at den har mistet effekt.","Når du forventer at andre skal tilpasse seg din foretrukne stil.","Når du lar endrede rammer føre til unødig frustrasjon eller treghet."],"overuse":["Når du lar hyppig tilpasning skape uforutsigbarhet.","Når du endrer standpunkt for å tilfredsstille andre.","Når du lar fleksibilitet gjøre prioriteringer eller prinsipper uklare."]},"barriers":["Du har sterke preferanser for hvordan arbeid bør gjøres.","Du tolker endring av plan som dårlig planlegging.","Du bruker konsistens som argument også når konteksten er ny."],"practice":{"effect":"Samarbeidet eller oppgaveløsningen forbedres uten at forventningene blir mindre klare.","experiment":"Velg én person eller situasjon hvor standardstilen din virker svakt, test en bevisst annen tilnærming og be om respons."},"reflection":[]}$competency$::jsonb),
    ('globalt-perspektiv', 'Globalt perspektiv', 'Global Perspective', 'strategy_business_change', 'Forstår hvordan markeder, institusjoner, kulturer og internasjonale avhengigheter påvirker virksomhetens valg og konsekvenser.', $competency${"schema_version":3,"relevant_when":"Rollen påvirkes av flere land eller markeder; egne normer behandles som universelle; lokale beslutninger får globale følger som overses.","distinction":"Velg Lede globale og distribuerte team når utviklingsbehovet gjelder den daglige ledelsen av et geografisk og kulturelt distribuert team.","best_practice":{"success":["Når du undersøker lokal kontekst uten å redusere mennesker til kulturelle stereotyper.","Når du ser globale avhengigheter, skjevheter og ringvirkninger.","Når du involverer lokale perspektiver før beslutning, ikke bare etterpå."],"underuse":["Når du behandler hjemmemarkedets antakelser som universelle.","Når du reduserer internasjonale forskjeller til språk eller etikette.","Når du tar globale beslutninger uten lokal innsikt."],"overuse":["Når du overvurderer lokale forskjeller slik at unødvendig kompleksitet skapes.","Når du bruker kulturelle forklaringer som stereotypier.","Når du retter så mye oppmerksomhet globalt at hjemmemarkedets realiteter undervurderes."]},"barriers":["Du bruker egen kontekst som normalpunkt.","Du søker global informasjon, men få lokale stemmer.","Du er rask til å forklare atferd med kultur."],"practice":{"effect":"Minst én beslutningspremiss eller gjennomføringsmåte blir justert.","experiment":"Test én viktig beslutning med to personer fra berørte markeder og be dem identifisere lokale antakelser og konsekvenser."},"reflection":[]}$competency$::jsonb),
    ('lede-globale-distribuerte-team', 'Lede globale og distribuerte team', 'Global Team Management', 'team_people', 'Skaper retning, tilhørighet og rettferdige arbeidsmåter i team på tvers av geografi, kultur og tidssoner.', $competency${"schema_version":3,"relevant_when":"Hovedkontoret dominerer; fjernmedlemmer har mindre innflytelse; avstand og ulik kontekst skaper misforståelser eller svak tilhørighet.","distinction":"Velg Teamledelse for teamdynamikk generelt. Denne kompetansen legger særlig vekt på avstand, ulikhet i makt og tilgang på informasjon, lokal kontekst og virtuelle arbeidsformer.","best_practice":{"success":["Når du etablerer tydelige spilleregler for kommunikasjon, beslutninger og tilgjengelighet.","Når du fordeler belastning, taletid og innflytelse mer rettferdig.","Når du bygger relasjon og tilhørighet utover formelle videomøter."],"underuse":["Når du lar hovedkontorets rytme og perspektiv bli standard for alle.","Når du lar avstand gi ulik tilgang til informasjon eller svekke relasjoner.","Når du bruker virtuelle møter uten bevisst design for deltakelse."],"overuse":["Når du lar koordinering bli så omfattende at teamet mister tempo.","Når du forklarer alle forskjeller med kultur eller geografi.","Når du prioriterer likhet i prosess foran rimelig lokal fleksibilitet."]},"barriers":["Du undervurderer hvor mye informasjon som spres uformelt lokalt.","Du planlegger møtet etter din egen arbeidstid.","Du tolker lav synlighet som lavt bidrag."],"practice":{"effect":"Deltakelse og beslutningspåvirkning blir jevnere fordelt.","experiment":"Roter møtetid, møteleder og rekkefølge på innspill i fire møter."},"reflection":[]}$competency$::jsonb),
    ('initiativ', 'Initiativ', 'Initiative', 'self_capacity', 'Oppdager behov og tar et ansvarlig første steg uten å vente på unødvendig styring.', $competency${"schema_version":3,"relevant_when":"Problemer blir stående fordi ingen eier dem; du venter på full avklaring eller tillatelse innenfor et allerede rimelig mandat.","distinction":"Velg Skape nødvendig fremdrift når saken er startet, men tempoet er for lavt. Velg Mot når sosial eller personlig risiko, ikke passivitet, er hovedbarrieren.","best_practice":{"success":["Når du ser muligheter og problemer tidlig.","Når du kobler problemforståelse til et ansvarlig neste steg.","Når du avklarer grensene for mandatet når risikoen tilsier det."],"underuse":["Når du venter på full bestilling i situasjoner hvor du kunne skapt fremdrift.","Når du lar muligheter bli stående fordi eierskap ikke er eksplisitt.","Når du løfter problemer uten å foreslå neste handling."],"overuse":["Når du starter tiltak uten å forstå prioritering, avhengigheter eller mandat.","Når du lar initiativ skape parallelle løp og fragmentering.","Når du lar handlekraft bli viktigere enn koordinering."]},"barriers":["Du vil være sikker på at du har mandat.","Du forbinder kvalitet med grundig forberedelse før første steg.","Du ser lett hvorfor noe ikke er ditt ansvar."],"practice":{"effect":"Saken beveger seg uten at ansvar eller styring blir uklart.","experiment":"Velg ett uavklart problem, formuler anbefaling, første steg og mandatgrense, og start innen én uke."},"reflection":[]}$competency$::jsonb),
    ('innovasjon', 'Innovasjon', 'Innovation', 'execution_decisions', 'Gjør nye ideer om til testede løsninger som skaper dokumenterbar verdi.', $competency${"schema_version":3,"relevant_when":"Ideer blir i presentasjoner; organisasjonen krever høy sikkerhet før små tester; læring fra forsøk brukes lite.","distinction":"Velg Kreativitet når mangelen på nye ideer og perspektiver er flaskehalsen. Innovasjon omfatter prioritering, eksperimentering, læring og implementering.","best_practice":{"success":["Når du definerer ønsket verdi og kritiske antakelser.","Når du tester tidlig, avgrenset og reversibelt.","Når du bruker resultater til å stoppe, endre eller skalere."],"underuse":["Når du lar ideer bli værende i idé- eller konseptfasen.","Når du bare forbedrer eksisterende praksis og sjelden tester nye modeller.","Når du lar læring fra eksperimenter stå uten konsekvens for videre investering."],"overuse":["Når du lar nyhet bli et mål i seg selv.","Når du lar for mange eksperimenter skape fragmentering.","Når du skalerer lovende konsepter før de viktigste antakelsene er testet."]},"barriers":["Du liker idéfasen bedre enn den disiplinerte testingen.","Du beskytter initiativer du selv har skapt.","Du måler aktivitet og interesse mer enn faktisk verdi."],"practice":{"effect":"Testen gir et tydelig grunnlag for å stoppe, endre eller gå videre.","experiment":"Test den mest usikre antakelsen i én idé med minst mulig ressursbruk."},"reflection":[]}$competency$::jsonb),
    ('mellommenneskelig-teft', 'Mellommenneskelig teft', 'Interpersonal Savvy', 'relationships_influence', 'Leser sosiale signaler, forstår hvordan ulike mennesker virker sammen og tilpasser eget samspill med presisjon.', $competency${"schema_version":3,"relevant_when":"Du overser reaksjoner i rommet; samme stil fungerer svært ulikt med forskjellige mennesker; oppgavefokus svekker relasjonen.","distinction":"Velg Relasjonsledelse når hovedbehovet er å bygge og vedlikeholde et strategisk relasjonsnettverk. Mellommenneskelig teft gjelder kvaliteten i selve samspillet.","best_practice":{"success":["Når du observerer ord, tone og kroppsspråk uten å trekke forhastede konklusjoner.","Når du tilpasser kontaktform, tempo og direktehet.","Når du tester egne fortolkninger gjennom spørsmål."],"underuse":["Når du overser signaler om hvordan budskap eller atferd lander.","Når du bruker samme stil uavhengig av person og situasjon.","Når du forklarer relasjonelle problemer som andres sensitivitet."],"overuse":["Når du overvåker rommet så mye at egen tydelighet svekkes.","Når du tilpasser deg så mye at det blir strategisk spill eller overtilpasning.","Når du bruker sosial smidighet til å unngå saklig konflikt."]},"barriers":["Du fokuserer på innhold og registrerer reaksjoner for sent.","Du antar at intensjonen din er synlig for andre.","Du tilpasser deg mest mennesker du allerede forstår godt."],"practice":{"effect":"Minst én antakelse blir korrigert før du handler på den.","experiment":"Observer reaksjoner i ett krevende møte, noter to hypoteser og test dem med åpne spørsmål."},"reflection":[]}$competency$::jsonb),
    ('lede-kultur', 'Lede kultur', 'Leading the Culture', 'strategy_business_change', 'Former felles normer gjennom det lederen modellerer, prioriterer, belønner, organiserer og tolererer.', $competency${"schema_version":3,"relevant_when":"Uttalte verdier og faktisk praksis spriker; uønsket atferd tolereres; kultur behandles som kommunikasjon fremfor et ledelsesansvar.","distinction":"Velg Lede med formål når meningen og hvorfor-et er uklart. Velg Gjennomføre endring når en definert ny arbeidspraksis skal innføres; kulturledelse gjelder de bredere normene som oppstår over tid.","best_practice":{"success":["Når du oversetter ønsket kultur til konkret atferd i hverdagen.","Når du samordner egen modellering, systemer, belønning og konsekvenser.","Når du undersøker faktisk praksis, også der budskapet er ubehagelig."],"underuse":["Når du omtaler kultur som verdier uten å koble dem til hverdagsatferd.","Når du tolererer uønsket atferd hos sterke prestasjonsutøvere.","Når du ber om én kultur, men belønner en annen."],"overuse":["Når du lar kulturarbeid bli normering av personlighet eller stil.","Når du krever så mye konsistens at nødvendig lokal variasjon forsvinner.","Når du prioriterer symboltiltak foran strukturelle drivere."]},"barriers":["Du tror kommunikasjon endrer kultur raskere enn systemer og lederatferd.","Du aksepterer avvik når resultatene er gode.","Du beskriver kultur med abstrakte ord."],"practice":{"effect":"Medarbeidere kan beskrive en konkret forskjell i hva som nå forventes eller tolereres.","experiment":"Velg én ønsket norm, identifiser hva som belønner og undergraver den, og endre én lederpraksis."},"reflection":[]}$competency$::jsonb),
    ('lede-med-formal', 'Lede med formål', 'Leading with Purpose', 'strategy_business_change', 'Knytter arbeid og prioriteringer til en troverdig forklaring på hvorfor virksomheten eller oppgaven betyr noe.', $competency${"schema_version":3,"relevant_when":"Arbeidet oppleves fragmentert eller meningsløst; ledelsen snakker mest om leveranser; formålet har liten konsekvens for prioriteringer.","distinction":"Velg Visjon når det mangler et konkret bilde av ønsket fremtid. Formål handler om hvorfor arbeidet er verdt å gjøre; visjon handler om hvor man skal.","best_practice":{"success":["Når du formulerer meningen konkret og uten abstrakt organisasjonsspråk.","Når du kobler daglige valg og ressursbruk til formålet.","Når du er åpen om spenninger mellom formål og andre hensyn."],"underuse":["Når du kommuniserer formålet uten å bruke det i faktiske valg.","Når du forklarer mål uten å vise hvorfor arbeidet betyr noe.","Når du lar kortsiktige hensyn konsekvent fortrenge uttalt retning."],"overuse":["Når du bruker formål som retorikk for å legitimere alle initiativer.","Når du lar mening erstatte tydelige mål og ansvar.","Når du lar formålsfortellingen bli så stor at den mister troverdighet."]},"barriers":["Du formulerer mening med for abstrakte ord.","Du bruker formålet mer i presentasjoner enn i prioriteringer.","Du antar at koblingen mellom oppgave og formål er åpenbar."],"practice":{"effect":"Teamet kan knytte egne oppgaver og ett konkret bortvalg til samme formål.","experiment":"Forklar én prioritering gjennom hvem den skaper verdi for, hvorfor det betyr noe og hva dere derfor velger bort."},"reflection":[]}$competency$::jsonb),
    ('forhandling', 'Forhandling', 'Negotiating', 'relationships_influence', 'Utvikler og inngår holdbare avtaler mellom parter med delvis sammenfallende og delvis motstridende interesser.', $competency${"schema_version":3,"relevant_when":"Ressurser, pris, ansvar eller vilkår skal avtales; du gir for lett etter eller låser deg til posisjon; alternativer er uklare.","distinction":"Velg Konflikthåndtering når relasjonell eller saklig konflikt må bearbeides før avtale. Velg Påvirkning når den andre skal støtte en retning uten et tydelig bytteforhold.","best_practice":{"success":["Når du forbereder interesser, prioriteringer, alternativer og grenser.","Når du utforsker før første løsning eller krav låses.","Når du bytter verdi på tvers av ulike prioriteringer og dokumenterer avtalen."],"underuse":["Når du går inn i forhandling uten tydelige prioriteringer eller alternativer.","Når du gir innrømmelser uten å få verdi tilbake.","Når du unngår å teste motpartens antakelser og grenser."],"overuse":["Når du behandler forhandling som konkurranse som må vinnes.","Når du lar taktikk svekke langsiktig tillit.","Når du presser avtalen så hardt at gjennomføringen eller relasjonen blir svak."]},"barriers":["Du forhandler på posisjoner før du forstår interesser.","Du blir ukomfortabel med stillhet og fyller den med innrømmelser.","Du overvurderer behovet for å lande avtalen."],"practice":{"effect":"Avtalen ivaretar de viktigste interessene uten unødvendige innrømmelser.","experiment":"Forbered neste forhandling med egne og antatte interesser, beste alternativ, grense og tre mulige bytter."},"reflection":[]}$competency$::jsonb),
    ('organisasjonsforstaelse', 'Organisasjonsforståelse', 'Organizational Savvy', 'strategy_business_change', 'Forstår hvordan formell myndighet, uformell innflytelse, interesser og beslutningsprosesser faktisk virker i organisasjonen.', $competency${"schema_version":3,"relevant_when":"Gode saker stopper av uklare grunner; du involverer feil personer eller for sent; organisasjonskartet brukes som beslutningskart.","distinction":"Velg Påvirkning når aktørene og dynamikken er forstått, men du trenger større oppslutning. Velg Forretnings- og fagforståelse når det er virksomhetslogikken, ikke makt- og beslutningsdynamikken, som mangler.","best_practice":{"success":["Når du kartlegger formelle beslutningseiere og uformelle påvirkere.","Når du forstår interesser og historikk uten å bli kynisk.","Når du bygger legitime relasjoner før støtte er nødvendig."],"underuse":["Når du forholder deg bare til organisasjonskartet.","Når du involverer viktige interessenter for sent.","Når du lar gode forslag stoppe fordi du undervurderer timing, historie eller uformell påvirkning."],"overuse":["Når du lar politisk navigering bli spill, alliansebygging eller informasjonskontroll.","Når du bruker uformelle kanaler til å omgå ansvar.","Når du lar hensynet til makt gjøre at faglig integritet svekkes."]},"barriers":["Du tror formelt mandat er det samme som faktisk påvirkning.","Du synes organisasjonspolitikk er noe man bør holde seg unna.","Du bygger støtte først etter at forslaget er ferdig."],"practice":{"effect":"En viktig aktør involveres tidligere eller på en mer relevant måte.","experiment":"Kartlegg beslutningseier, påvirkere, interesser og mulige motforestillinger i én sak; test kartet med en erfaren kollega."},"reflection":[]}$competency$::jsonb),
    ('problemlosning', 'Problemløsning', 'Problem Solving', 'execution_decisions', 'Definerer problemer presist, undersøker årsaker og utvikler løsninger som treffer mer enn de synlige symptomene.', $competency${"schema_version":3,"relevant_when":"Teamet hopper til løsning; samme problem vender tilbake; data brukes til å bekrefte første hypotese.","distinction":"Velg Beslutningstaking når alternativene er gode nok, men valg og forpliktelse svikter. Velg Løsningskraft under begrensninger når problemet er kjent, men ressurser eller tilgang er hovedbarrieren.","best_practice":{"success":["Når du skiller fakta, symptomer, årsaker og problemformulering.","Når du bruker relevante data og motstridende perspektiver.","Når du tester om løsningen treffer årsaken og unngår uønskede følger."],"underuse":["Når du løser det mest synlige symptomet.","Når du lar første forklaring bli stående uten å testes.","Når du lar samme problem komme tilbake fordi årsaken ikke ble adressert."],"overuse":["Når du lar analysen bli mer omfattende enn problemets betydning tilsier.","Når du leter etter rotårsaken så lenge at nødvendig skadebegrensning forsinkes.","Når du lar modeller erstatte praktisk testing."]},"barriers":["Du får energi av løsninger og går for raskt dit.","Du behandler antakelser som fakta.","Du søker én rotårsak i problemer som egentlig skapes av flere forhold."],"practice":{"effect":"Problemdefinisjonen endres eller styrkes før løsning velges.","experiment":"Formuler én utfordring på tre måter, identifiser data som kan avkrefte hver formulering og test den mest kritiske antakelsen."},"reflection":[]}$competency$::jsonb),
    ('relasjonsledelse', 'Relasjonsledelse', 'Relationship Management', 'relationships_influence', 'Bygger, vedlikeholder og reparerer arbeidsrelasjoner som er nødvendige for samarbeid og resultater over tid.', $competency${"schema_version":3,"relevant_when":"Kontakten er behovsstyrt; kritiske relasjoner forsømmes; små brudd eller uavklarte forventninger svekker samarbeid.","distinction":"Velg Mellommenneskelig teft når utfordringen er kvaliteten på det konkrete samspillet. Velg Eksterne partnerskap for strategiske relasjoner mellom organisasjoner.","best_practice":{"success":["Når du prioriterer relasjoner ut fra betydning og gjensidig verdi.","Når du følger opp kontakt, forpliktelser og uavklarte spenninger.","Når du reparerer brudd uten å late som uenighet ikke finnes."],"underuse":["Når du lar relasjoner bli rent transaksjonelle.","Når du forsømmer viktige forbindelser mellom leveranser.","Når du lar uavklarte misforståelser få akkumulere."],"overuse":["Når du bruker så mye tid på relasjoner at nødvendige beslutninger eller prestasjonskrav skyves ut.","Når du unngår uenighet for å bevare relasjonen.","Når du lar nettverk bli bredt, men overfladisk og lite gjensidig."]},"barriers":["Du tar gode relasjoner for gitt.","Du kontakter mennesker mest når du trenger noe.","Du venter for lenge med å reparere små brudd."],"practice":{"effect":"En konkret gjensidig forventning eller arbeidsform blir forbedret.","experiment":"Velg én kritisk forsømt relasjon, ta kontakt uten bestilling og avklar hva et bedre samarbeid krever fra begge."},"reflection":[]}$competency$::jsonb),
    ('motstandskraft', 'Motstandskraft', 'Resilience', 'self_capacity', 'Bevarer eller gjenoppretter regulering, perspektiv og funksjon under press, usikkerhet og tilbakeslag.', $competency${"schema_version":3,"relevant_when":"Stress snevrer inn dømmekraften; du bruker lang tid på å hente deg inn; tilbakeslag blir tolket som varige nederlag.","distinction":"Velg Bærekraftig kapasitet og prioritering når vedvarende belastningsdesign og grenser er hovedproblemet. Motstandskraft gjelder respons og restitusjon når belastning faktisk oppstår.","best_practice":{"success":["Når du gjenkjenner tidlige tegn på redusert kapasitet.","Når du regulerer intensitet og bruker støtte og restitusjon aktivt.","Når du trekker læring uten å romantisere belastningen."],"underuse":["Når du lar motgang føre til langvarig tap av fokus eller handlekraft.","Når du skjuler belastning til funksjonen allerede er svekket.","Når du tolker ett tilbakeslag som et mål på hva du eller andre kan."],"overuse":["Når du lar robusthet bli en forventning om å tåle urimelig belastning.","Når du går videre så raskt at læring eller reell restitusjon uteblir.","Når du behandler sårbarhet og behov for støtte som svakhet."]},"barriers":["Du tror du bør håndtere press alene.","Du merker egne grenser sent.","Du tolker restitusjon som tid tatt fra prestasjon."],"practice":{"effect":"Du oppdager kapasitetsfall tidligere og gjenoppretter funksjon raskere.","experiment":"Definer egne tidlige tegn, to reguleringsgrep og én person du kontakter i en krevende periode; bruk planen bevisst."},"reflection":[]}$competency$::jsonb),
    ('losningskraft-under-begrensninger', 'Løsningskraft under begrensninger', 'Resourcefulness', 'execution_decisions', 'Mobiliserer tilgjengelige mennesker, kunnskap og ressurser for å skape praktisk fremdrift når rammene er ufullstendige.', $competency${"schema_version":3,"relevant_when":"Arbeid stopper fordi ønskede ressurser mangler; du forsøker å løse alt alene; muligheter i eksisterende nettverk og ressurser overses.","distinction":"Velg Problemløsning når årsaksforståelsen er svak. Velg Initiativ når barrieren er å ta første steg, ikke å finne alternative midler.","best_practice":{"success":["Når du avklarer hva som er godt nok til neste steg.","Når du finner og kombinerer ressurser utover egen enhet.","Når du skaper midlertidige, ansvarlige løsninger uten å skjule langsiktig behov."],"underuse":["Når du lar manglende ressurser bli forklaring på manglende fremdrift.","Når du venter på ideelle rammer før du handler.","Når du overser tilgjengelige nettverk eller eksisterende løsninger."],"overuse":["Når du lar improvisasjon erstatte nødvendig investering eller kvalitet.","Når du lar snarveier skape risiko som andre må bære.","Når du løser kapasitetsproblemer i systemet med stadig mer personlig innsats."]},"barriers":["Du ser først hva som mangler.","Du ber sent om hjelp.","Du antar at etablerte prosesser er den eneste legitime veien."],"practice":{"effect":"Saken beveger seg uten ny hovedressurs og uten brudd på kritiske krav.","experiment":"Velg én blokkert sak og kartlegg hva dere har, hvem som kan bidra og minste forsvarlige neste steg."},"reflection":[]}$competency$::jsonb),
    ('gjennomtenkt-risikovilje', 'Gjennomtenkt risikovilje', 'Risk Taking', 'self_capacity', 'Tar bevisst risiko når mulig verdi forsvarer usikkerheten, og begrenser konsekvensene der det er mulig.', $competency${"schema_version":3,"relevant_when":"Kravet om sikkerhet hindrer læring eller muligheter; kostnaden ved å ikke handle overses; reversible valg behandles som irreversible.","distinction":"Velg Mot når den sentrale risikoen er sosial, etisk eller knyttet til egen posisjon. Velg Beslutningstaking når prosessen for valg generelt er problemet.","best_practice":{"success":["Når du vurderer mulig gevinst, tap, om valget kan gjøres om og kostnaden ved å vente.","Når du gjør antakelser og tiltak som reduserer risiko tydelige.","Når du skiller intelligent risiko fra uforsiktighet."],"underuse":["Når du velger det kjente selv om forventet verdi er lavere.","Når du lar frykt for feil stoppe læring eller nødvendig innovasjon.","Når du utsetter beslutninger til muligheten er borte."],"overuse":["Når du tar risiko for spenning, synlighet eller tempo uten tilstrekkelig oppside.","Når du tar risiko der andre bærer nedsiden uten å forstå den.","Når du bruker læring som unnskyldning for svak risikostyring."]},"barriers":["Du overvurderer kostnaden ved å feile.","Du trenger sosial trygghet før du prøver noe nytt.","Du vurderer risiko uten å vurdere risikoen ved å la være."],"practice":{"effect":"Læring eller verdi oppstår tidligere, mens nedsiden forblir innen avtalt grense.","experiment":"Velg én reversibel beslutning, beskriv beste, verste og mest sannsynlige utfall samt stoppsignal, og ta den raskere."},"reflection":[]}$competency$::jsonb),
    ('egenutvikling', 'Egenutvikling', 'Self-Development', 'self_capacity', 'Tar langsiktig ansvar for å utvikle kapasitet som nåværende og fremtidige roller krever.', $competency${"schema_version":3,"relevant_when":"Utvikling blir tilfeldig eller utsettes; du har mange mål uten praksis; innsikt samles uten endret atferd.","distinction":"Velg Læringssmidighet når behovet er å lære bedre fra løpende erfaring og overføre læringen. Egenutvikling gjelder retning, prioritering og vedvarende oppfølging av egen utvikling.","best_practice":{"success":["Når du prioriterer få utviklingsmål ut fra rolle og fremtidige krav.","Når du bruker arbeidserfaring, feedback, refleksjon og faglig input sammen.","Når du følger opp faktisk endring over tid."],"underuse":["Når du lar utvikling bli tilfeldig eller drevet av det som er interessant fremfor viktig.","Når du får innsikt uten å omsette den i øvelse.","Når du venter på at organisasjonen skal definere og drive utviklingen din."],"overuse":["Når du lar utvikling bli et kontinuerlig selvforbedringsprosjekt uten prioritering.","Når du samler kurs og modeller uten praksis.","Når du lar fokus på svakheter fortrenge bruk og videreutvikling av styrker."]},"barriers":["Du setter for mange utviklingsmål samtidig.","Du forveksler forståelse med mestring.","Du velger læring som er komfortabel fremfor nødvendig."],"practice":{"effect":"Feedbackpersonene kan beskrive en konkret forskjell ved periodens slutt.","experiment":"Velg én atferd for de neste åtte ukene, én treningsarena og to feedbackpersoner."},"reflection":["Hvilken én atferd er viktigere å øve på nå enn å lære mer om?"]}$competency$::jsonb),
    ('strategisk-retning', 'Strategisk samordning', 'Strategic Alignment', 'strategy_business_change', 'Sørger for at mål, prioriteringer, ressurser, oppfølging og avhengigheter trekker i samme strategiske retning.', $competency${"schema_version":3,"relevant_when":"Alt er prioritert; lokale mål motvirker helheten; strategien har liten konsekvens for ressursbruk og daglige valg.","distinction":"Velg Strategisk planlegging og gjennomføring når retningen må omsettes til initiativer, ansvar og milepæler. Samordning handler særlig om konsistens på tvers.","best_practice":{"success":["Når du tester initiativer og ressursbruk mot tydelige strategiske valg.","Når du synliggjør og håndterer målkonflikter mellom enheter.","Når du avklarer kritiske avhengigheter og felles prioriteringer."],"underuse":["Når du lar strategi og portefølje leve som separate verdener.","Når du lar enheter prioritere egne mål på bekostning av helheten.","Når du omtaler alt som strategisk og reelle valg uteblir."],"overuse":["Når du lar samordning bli krav om likhet der lokal tilpasning er nødvendig.","Når du lar koordinering bli så omfattende at tempo forsvinner.","Når du bruker strategi til å stoppe initiativ uten å vurdere ny informasjon."]},"barriers":["Du ser tydelig hva din enhet skal gjøre, men mindre på tvers.","Du lar eksisterende ressursfordeling definere prioriteringene.","Du unngår å si tydelig hva som skal velges bort."],"practice":{"effect":"Ressurser flyttes faktisk, ikke bare etikettene.","experiment":"Kartlegg fem større aktiviteter mot tre strategiske prioriteringer og stopp, endre eller nedprioriter minst én."},"reflection":[]}$competency$::jsonb),
    ('strategisk-planlegging-og-gjennomforing', 'Strategisk planlegging og gjennomføring', 'Strategic Planning and Implementation', 'strategy_business_change', 'Oversetter langsiktig retning til få prioriteringer, sammenhengende initiativer, ansvar og lærende gjennomføring.', $competency${"schema_version":3,"relevant_when":"Strategien blir aktivitetsliste; gjennomføringen er svakere enn planleggingen; for mange initiativer konkurrerer om kapasitet.","distinction":"Velg Visjon når ønsket fremtid er uklar. Velg Strategisk samordning når planene finnes, men mål og ressurser trekker i ulike retninger.","best_practice":{"success":["Når du gjør eksplisitte valg om hva som skal og ikke skal gjøres.","Når du kobler ønsket effekt til initiativer, eiere, ressurser og milepæler.","Når du reviderer antakelser og plan når omgivelsene endrer seg."],"underuse":["Når du lar strategien bli ambisjon uten tydelige valg.","Når du starter initiativer uten tydelig eierskap, ressurser eller målbar fremdrift.","Når du lar årlig plan erstatte løpende strategisk læring."],"overuse":["Når du lar planen bli så detaljert at den gir falsk sikkerhet.","Når du låser gjennomføring til opprinnelig plan selv om premissene endres.","Når du lar strategiprosessen bli større enn de strategiske valgene."]},"barriers":["Du liker komplette planer før handling.","Du blander mål, tiltak og ønskede resultater.","Du følger aktivitet tettere enn om strategiske antakelser holder."],"practice":{"effect":"Teamet kan prioritere en ny forespørsel uten å eskalere fordi valgene er klare.","experiment":"Reduser én plan til tre avgjørende valg, ønsket effekt, eier, tidlig indikator og eksplisitt bortvalg."},"reflection":[]}$competency$::jsonb),
    ('systemtenkning', 'Systemtenkning', 'Systems Thinking', 'strategy_business_change', 'Ser mønstre, tilbakekoblinger, avhengigheter, forsinkelser og målkonflikter som former resultatene i et større system.', $competency${"schema_version":3,"relevant_when":"Lokale forbedringer skaper problemer andre steder; komplekse utfordringer behandles lineært; utilsiktede konsekvenser gjentar seg.","distinction":"Velg Problemløsning for et mer avgrenset problem med identifiserbare årsaker. Systemtenkning er særlig relevant når årsak og virkning er spredt over tid, nivåer og aktører.","best_practice":{"success":["Når du kartlegger aktører, insentiver, avhengigheter og hvordan de påvirker hverandre.","Når du undersøker ringvirkninger og forsinkede effekter.","Når du gjør målkonflikter tydelige fremfor å late som alt kan maksimeres."],"underuse":["Når du velger lokale løsninger som flytter problemet til en annen del av systemet.","Når du behandler hendelser isolert uten å se gjentakende mønstre.","Når du overser insentiver, struktur eller avhengigheter."],"overuse":["Når du analyserer systemet så omfattende at ingen handler.","Når du forklarer alt med systemet og individuelt ansvar blir uklart.","Når du bruker kompleksitet som argument mot enkle, virksomme tiltak."]},"barriers":["Du løser problemer der de blir synlige.","Du undervurderer tidsforsinkelser og indirekte effekter.","Du søker én årsak i problemer med flere gjensidige drivere."],"practice":{"effect":"Tiltaket retter seg mot en mekanisme, ikke bare et symptom.","experiment":"Tegn systemet rundt én gjentakende utfordring og identifiser én tilbakekobling, én forsinkelse og ett mulig inngrepspunkt."},"reflection":[]}$competency$::jsonb),
    ('rekruttere-og-beholde-talent', 'Rekruttere og beholde talent', 'Talent Recruitment and Retention', 'team_people', 'Bygger den kapasiteten virksomheten trenger ved å tiltrekke, velge, utvikle og beholde relevante mennesker over tid.', $competency${"schema_version":3,"relevant_when":"Teamet mangler fremtidig kapasitet; rekruttering gjentar samme profil; nøkkelpersoner forlater uten at årsakene er forstått.","distinction":"Velg Utvikle andre når behovet primært gjelder vekst hos nåværende medarbeidere. Denne kompetansen omfatter den bredere talentporteføljen og arbeidsmiljøets attraktivitet.","best_practice":{"success":["Når du avklarer hvilke kompetanser virksomheten trenger før du definerer profil og kandidat.","Når du vurderer potensial, dokumentert erfaring og hva kandidaten tilfører teamet.","Når du bruker utvikling, ledelseskvalitet og arbeidsvilkår aktivt for å beholde talent."],"underuse":["Når du starter rekrutteringen med CV-profiler fremfor rollebehov.","Når du diskuterer utvikling og karrieremuligheter først ved fare for avgang.","Når du tar sterke prestasjoner som tegn på at personen er tilfreds."],"overuse":["Når du lar talentarbeid bli særbehandling av en liten elite.","Når du holder mennesker i roller de har vokst ut av for å beholde dem.","Når du overvurderer potensial på bekostning av dokumentert prestasjon og kravene i rollen."]},"barriers":["Du rekrutterer mennesker du intuitivt liker eller kjenner deg igjen i.","Du tar nøkkelpersoners lojalitet for gitt.","Du utsetter karrieresamtaler fordi du ikke kan love neste rolle."],"practice":{"effect":"Ett konkret tiltak endres i arbeidsmiljø, utvikling eller bemanningsplan.","experiment":"Gjennomfør tre stay-samtaler og kartlegg ett fremtidig kompetansegap uten å starte med dagens stillinger."},"reflection":[]}$competency$::jsonb),
    ('teamledelse', 'Teamledelse', 'Team Leadership', 'team_people', 'Leder teamet som et gjensidig avhengig system med felles retning, tydelige roller og arbeidsmåter som støtter samlet prestasjon.', $competency${"schema_version":3,"relevant_when":"Du leder enkeltpersoner, men ikke samspillet; roller og avhengigheter er uklare; harmoni skjuler svak koordinering eller nødvendig uenighet.","distinction":"Velg Lede gjennom andre når hele arbeidsorganiseringen og beslutningsfordelingen gjør lederen til flaskehals. Velg Lede globale og distribuerte team når avstand og lokal kontekst er den særskilte utfordringen.","best_practice":{"success":["Når du etablerer felles leveranse, beslutningsmåte og gjensidige forpliktelser.","Når du gjør roller, avhengigheter og samarbeidsflater tydelige.","Når du arbeider med samspillsmønstre, ikke bare enkeltprestasjoner."],"underuse":["Når du leder teamet som en samling individuelle leverandører.","Når du lar uklare roller eller beslutningsprosesser skape friksjon.","Når du behandler relasjonelle problemer som individproblemer fremfor teammønstre."],"overuse":["Når du bruker mer tid på teamprosesser enn oppgaven krever.","Når du lar konsensus bli standard for beslutninger som trenger tydelig eierskap.","Når du gjør teamet avhengig av deg for koordinering og konfliktløsning."]},"barriers":["Du løser problemer én-til-én som egentlig tilhører teamet.","Du antar at flinke individer automatisk blir et godt team.","Du griper inn for raskt når teamet strever."],"practice":{"effect":"Teamet endrer én arbeidsmåte og kan vise bedre koordinering i en konkret leveranse.","experiment":"La teamet kartlegge viktigste felles leveranse, tre avhengigheter og ett mønster som hemmer dem."},"reflection":[]}$competency$::jsonb),
    ('tidsstyring', 'Tidsstyring', 'Time Management', 'self_capacity', 'Bruker oppmerksomhet og tid i tråd med viktigste ansvar, og designer arbeidsflyten for konsentrasjon og fremdrift.', $competency${"schema_version":3,"relevant_when":"Innboks og møter styrer dagen; kjernearbeid skyves; kalenderen gjenspeiler ikke prioriteringene.","distinction":"Velg Bærekraftig kapasitet og prioritering når utfordringen også omfatter grenser, vedvarende belastning og restitusjon. Tidsstyring er mer operativt.","best_practice":{"success":["Når du planlegger arbeidet med størst verdi før kalenderen fylles.","Når du samler, forkorter, delegerer eller fjerner aktiviteter med lav verdi.","Når du beskytter konsentrasjon og har en realistisk buffer."],"underuse":["Når du lar andres forespørsler styre kalenderen.","Når du stadig skyver viktige oppgaver som ikke haster.","Når du undervurderer tidsbruk og skaper kronisk overbooking."],"overuse":["Når du lar planlegging bli så rigid at reelle endringer ikke håndteres.","Når du behandler relasjonelle eller kreative behov som forstyrrelser i effektivitetens navn.","Når du fyller alle ledige flater og ikke lar noen buffer stå igjen."]},"barriers":["Du likestiller tilgjengelighet med god ledelse.","Du sier ja før du vurderer hva det fortrenger.","Du planlegger for idealuke, ikke faktisk variasjon."],"practice":{"effect":"En definert kjerneleveranse får mer sammenhengende tid og færre utsettelser.","experiment":"Kod to kalenderuker etter strategisk verdi, drift og friksjon; flytt minst ti prosent til viktig kjernearbeid."},"reflection":[]}$competency$::jsonb),
    ('tvetydighet', 'Navigere i usikkerhet', 'Tolerating Ambiguity', 'self_capacity', 'Bevarer nysgjerrighet, vurderingsevne og handlingskraft når informasjon, retning eller utfall ikke er entydig.', $competency${"schema_version":3,"relevant_when":"Du søker premature svar; blir passiv uten full informasjon; låser deg raskt til én fortolkning for å redusere ubehag.","distinction":"Velg Tilpasse seg endring når rammene faktisk er endret og reaksjonen gjelder tap eller overgang. Velg Beslutningstaking når det gjelder en konkret beslutningsprosess.","best_practice":{"success":["Når du holder flere plausible forklaringer åpne.","Når du skiller hva som må avklares nå fra hva som kan forbli uavklart.","Når du tar steg som kan gjøres om, mens du følger med på kritisk usikkerhet."],"underuse":["Når du venter på klarhet situasjonen ikke kan gi.","Når du lar usikkerhet føre til overanalyse eller passivitet.","Når du skaper falsk sikkerhet for å redusere eget eller andres ubehag."],"overuse":["Når du lar toleranse for uklarhet bli aksept for dårlig retning eller manglende beslutninger.","Når du lar viktige spørsmål stå åpne unødvendig lenge.","Når du lar fleksibilitet gjøre at andre ikke vet hva som faktisk gjelder."]},"barriers":["Du opplever åpne spørsmål som uferdig arbeid.","Du søker mer data selv når den neppe vil redusere usikkerheten.","Du kommuniserer mer sikkerhet enn beslutningsgrunnlaget tilsier."],"practice":{"effect":"Arbeidet beveger seg uten at usikkerheten skjules eller må løses kunstig.","experiment":"Beskriv tre plausible scenarioer, felles robuste handlinger og ett signal som utløser kursendring."},"reflection":[]}$competency$::jsonb),
    ('tillit', 'Bygge tillit', 'Trust', 'relationships_influence', 'Skaper trygghet for samarbeid gjennom pålitelighet, åpenhet, kompetanse, omtanke og ansvarlig tillit til andre.', $competency${"schema_version":3,"relevant_when":"Informasjon holdes tilbake; mennesker kontrollerer hverandre unødvendig; forpliktelser eller intensjoner blir møtt med skepsis.","distinction":"Velg Troverdighet og integritet når avstanden mellom egne prinsipper, ord og handling er hovedproblemet. Tillit er en relasjonell vurdering og kan ikke kreves ensidig.","best_practice":{"success":["Når du holder, avklarer eller reforhandler forpliktelser.","Når du deler relevant informasjon og begrunnelse innen forsvarlige rammer.","Når du tilpasser handlingsrom og oppfølging til risikoen uten skjult kontroll."],"underuse":["Når du holder tilbake ansvar eller informasjon uten saklig grunn.","Når du lover mer enn du kan levere.","Når du bruker kontroll som standard fordi du ikke har eksplisitt vurdert risiko."],"overuse":["Når du lar tillit bli naivitet og nødvendig kontroll eller verifikasjon uteblir.","Når du lar fortrolighet føre til utydelige grenser.","Når du gir stort handlingsrom uten å avklare ansvar."]},"barriers":["Du sier at du stoler på andre, men beholder beslutningene.","Du undervurderer effekten av små brutte avtaler.","Du unngår å snakke eksplisitt om tillit når den er svekket."],"practice":{"effect":"Mindre dobbeltkontroll, raskere informasjonsdeling eller tidligere varsling av problemer.","experiment":"Spør én viktig relasjon hva som ville gjort samarbeidet mer forutsigbart og trygt; avtal én gjensidig praksis."},"reflection":[]}$competency$::jsonb),
    ('skape-nodvendig-fremdrift', 'Skape nødvendig fremdrift', 'Urgency', 'self_capacity', 'Øker tempoet i viktige saker når timing har verdi, uten å gjøre konstant hastverk til normaltilstand.', $competency${"schema_version":3,"relevant_when":"Saker driver uten eier eller frist; reversible beslutninger behandles langsomt; perfeksjon forsinker læring eller resultat.","distinction":"Velg Initiativ når saken ikke er startet. Velg Tidsstyring når personlig arbeidsflyt og kalender er hovedproblemet. Fremdrift gjelder tempoet i en konkret viktig sak.","best_practice":{"success":["Når du skiller det som faktisk haster fra opplevd travelhet.","Når du avklarer neste steg, eier og en nær frist for beslutningen.","Når du fjerner venting og unødvendige overleveringer."],"underuse":["Når du lar viktige saker bli liggende fordi ingen skaper tempo.","Når du fortsetter å analysere eller involvere etter at beslutningsgrunnlaget er godt nok.","Når du undervurderer konsekvensen av forsinkelse."],"overuse":["Når du behandler alt som hastesak.","Når du lar tempo skape feil, omarbeid eller utmattelse.","Når du presser andre uten å fjerne hindringer eller gjøre prioriteringer."]},"barriers":["Du bruker grundighet også når kostnaden ved venting er høy.","Du avklarer ikke frist eller eier tydelig nok.","Du forveksler aktivitet med fremdrift."],"practice":{"effect":"Gjennomløpstiden faller uten økning i feil eller uklarhet.","experiment":"Velg én treg sak, kartlegg ventetid og reduser én godkjenning eller overlevering; sett eier og frist."},"reflection":[]}$competency$::jsonb),
    ('visjon', 'Visjon', 'Vision', 'strategy_business_change', 'Formulerer et konkret, troverdig og attraktivt bilde av en ønsket fremtid som gir retning til valg i dag.', $competency${"schema_version":3,"relevant_when":"Målene er tall uten fremtidsbilde; mennesker forstår ikke hvor organisasjonen skal; prioriteringer mangler en samlende retning.","distinction":"Velg Lede med formål når hvorfor-et og meningen er uklart. Velg Strategisk planlegging og gjennomføring når fremtidsbildet finnes, men veien, valgene og ansvaret mangler.","best_practice":{"success":["Når du beskriver en ønsket fremtid konkret nok til at forskjellen fra i dag er synlig.","Når du forbinder fremtidsbildet med behov, identitet og realistiske muligheter.","Når du bruker visjonen som beslutningskriterium, ikke bare kommunikasjon."],"underuse":["Når du beskriver et så generelt fremtidsbilde at det ikke skaper valg.","Når du formidler mål uten å beskrive hvilken fremtid dere forsøker å bygge.","Når du ikke kobler kortsiktige beslutninger til retningen."],"overuse":["Når du lar visjonen bli grandios eller løsrevet fra realiteter.","Når du lar inspirerende språk erstatte strategiske valg.","Når du blir så knyttet til fremtidsbildet at signaler om behov for endring ignoreres."]},"barriers":["Du beskriver retning med abstrakte ord.","Du antar at andre ser samme fremtidsbilde som deg.","Du kommuniserer visjonen oftere enn du bruker den til å velge bort."],"practice":{"effect":"Medarbeidere kan gjenfortelle retningen og bruke den i et reelt prioriteringsvalg.","experiment":"Beskriv ønsket fremtid på én side med tre observerbare forskjeller fra i dag og tre valg den krever nå."},"reflection":[]}$competency$::jsonb),
    ('lede-gjennom-andre', 'Lede gjennom andre', 'Working through Others', 'team_people', 'Organiserer ansvar, beslutninger, kapasitet og oppfølging slik at resultater skapes gjennom et fungerende system, ikke lederens egen produksjon.', $competency${"schema_version":3,"relevant_when":"Arbeid stopper når du er borte; for mange beslutninger samles hos deg; teamet er avhengig av din detaljinvolvering.","distinction":"Velg Delegering for én konkret overføring av ansvar. Velg Teamledelse når teamets felles mål og samspill er hovedproblemet. Lede gjennom andre gjelder lederens samlede arbeidsmodell.","best_practice":{"success":["Når du plasserer ansvar og beslutningsmyndighet nær relevant kunnskap.","Når du sørger for kapasitet, tydelige samarbeidsflater og avklarte eskaleringspunkter.","Når du følger opp resultater og system, ikke alle detaljer."],"underuse":["Når du selv blir flaskehals for beslutninger eller kvalitet.","Når du lar teamet vente på deg for koordinering, problemløsning eller godkjenning.","Når du prioriterer din egen produksjon foran å bygge andres kapasitet."],"overuse":["Når du trekker deg for langt unna og kaller det myndiggjøring.","Når du skyver ansvar ned uten tydelig retning eller nødvendige ressurser.","Når du bruker struktur og delegering til å distansere deg fra eget lederansvar."]},"barriers":["Du får sterk identitet og trygghet av å være den som leverer.","Du stoler mer på egen kvalitet enn på systemet rundt deg.","Du griper inn når andre løser oppgaven annerledes enn du ville gjort."],"practice":{"effect":"Arbeidet fortsetter med forsvarlig kvalitet uten lederens løpende godkjenning.","experiment":"Kartlegg hva som stopper ved to ukers fravær, flytt én beslutning og definer ramme og eskalering."},"reflection":[]}$competency$::jsonb)
)
update public.leadership_competencies competency
set
  title_no = editorial.title_no,
  title_en = editorial.title_en,
  category = editorial.category,
  summary = editorial.summary,
  content_json = competency.content_json || editorial.payload
from editorial
where competency.slug = editorial.slug;

do $$
begin
  if (
    select count(*)
    from public.leadership_competencies
    where is_active
      and coalesce((content_json ->> 'schema_version')::integer, 0) = 3
  ) <> 52 then
    raise exception 'Expected all 52 active leadership competencies to have content schema v3';
  end if;
end
$$;

comment on column public.leadership_competencies.content_json is
  'Versioned competency content. Schema v3 completes distinct success, underuse, miscalibration and barrier arrays while retaining legacy compatibility keys.';
